import sys

sys.setrecursionlimit(10000)


class ExprError(Exception):
    def __init__(self, kind, pos):
        self.kind = kind
        self.pos = pos
        super().__init__(kind, pos)


def _is_int(v):
    return type(v) is int


def _is_bool(v):
    return type(v) is bool


class _Tokenizer:
    __slots__ = ("src", "i", "n", "peeked")

    _TWO_OPS = frozenset(("||", "&&", "==", "!=", "<=", ">=", "**"))
    _ONE_OPS = frozenset("!?-+*/%<>()?:,")

    def __init__(self, src):
        self.src = src
        self.i = 0
        self.n = len(src)
        self.peeked = None

    def peek(self):
        if self.peeked is None:
            self.peeked = self._scan()
        return self.peeked

    def advance(self):
        if self.peeked is not None:
            tok = self.peeked
            self.peeked = None
            return tok
        return self._scan()

    def _scan(self):
        s = self.src
        n = self.n
        i = self.i

        while i < n:
            c = s[i]
            if c in (" ", "\t", "\n", "\r"):
                i += 1
            else:
                break
        self.i = i

        if i >= n:
            return ("end", None, n)

        c = s[i]

        if "0" <= c <= "9":
            start = i
            i += 1
            while i < n and "0" <= s[i] <= "9":
                i += 1
            if i - start > 1 and s[start] == "0":
                raise ExprError("syntax", start)
            self.i = i
            return ("int", int(s[start:i]), start)

        if c == "_" or "A" <= c <= "Z" or "a" <= c <= "z":
            start = i
            i += 1
            while i < n:
                c2 = s[i]
                if c2 == "_" or "A" <= c2 <= "Z" or "a" <= c2 <= "z" or "0" <= c2 <= "9":
                    i += 1
                else:
                    break
            word = s[start:i]
            self.i = i
            if word == "true":
                return ("bool", True, start)
            if word == "false":
                return ("bool", False, start)
            return ("ident", word, start)

        two = s[i:i + 2]
        if two in self._TWO_OPS:
            self.i = i + 2
            return ("op", two, i)

        if c in self._ONE_OPS:
            self.i = i + 1
            return ("op", c, i)

        raise ExprError("syntax", i)


class _Parser:
    def __init__(self, src):
        self.tk = _Tokenizer(src)

    def _peek(self):
        return self.tk.peek()

    def _consume(self):
        return self.tk.advance()

    def parse(self):
        node = self.parse_ternary()
        tok = self._peek()
        if tok[0] != "end":
            raise ExprError("syntax", tok[2])
        return node

    def parse_ternary(self):
        stack = []
        node = self.parse_level2()

        while True:
            tok = self._peek()

            if tok[0] == "op" and tok[1] == ":":
                while stack and stack[-1][2] is not None:
                    cond, qpos, true = stack.pop()
                    node = ("ternary", cond, true, node, qpos)

                if not stack:
                    raise ExprError("syntax", tok[2])

                self._consume()
                stack[-1][2] = node
                node = self.parse_level2()

            elif tok[0] == "op" and tok[1] == "?":
                self._consume()
                stack.append([node, tok[2], None])
                node = self.parse_level2()

            else:
                while stack and stack[-1][2] is not None:
                    cond, qpos, true = stack.pop()
                    node = ("ternary", cond, true, node, qpos)

                if stack:
                    raise ExprError("syntax", tok[2])

                return node

    def parse_level2(self):
        node = self.parse_level3()
        while True:
            tok = self._peek()
            if tok[0] == "op" and tok[1] == "||":
                self._consume()
                right = self.parse_level3()
                node = ("binary", "||", node, right, tok[2])
            else:
                break
        return node

    def parse_level3(self):
        node = self.parse_level4()
        while True:
            tok = self._peek()
            if tok[0] == "op" and tok[1] == "&&":
                self._consume()
                right = self.parse_level4()
                node = ("binary", "&&", node, right, tok[2])
            else:
                break
        return node

    def parse_level4(self):
        node = self.parse_level5()
        tok = self._peek()
        if tok[0] == "op" and tok[1] in ("==", "!="):
            self._consume()
            right = self.parse_level5()
            node = ("binary", tok[1], node, right, tok[2])
        return node

    def parse_level5(self):
        node = self.parse_level6()
        tok = self._peek()
        if tok[0] == "op" and tok[1] in ("<", "<=", ">", ">="):
            self._consume()
            right = self.parse_level6()
            node = ("binary", tok[1], node, right, tok[2])
        return node

    def parse_level6(self):
        node = self.parse_level7()
        while True:
            tok = self._peek()
            if tok[0] == "op" and tok[1] in ("+", "-"):
                self._consume()
                right = self.parse_level7()
                node = ("binary", tok[1], node, right, tok[2])
            else:
                break
        return node

    def parse_level7(self):
        node = self.parse_power()
        while True:
            tok = self._peek()
            if tok[0] == "op" and tok[1] in ("*", "/", "%"):
                self._consume()
                right = self.parse_power()
                node = ("binary", tok[1], node, right, tok[2])
            else:
                break
        return node

    def parse_power(self):
        segments = []
        ops = []

        while True:
            unary_ops = []
            while True:
                tok = self._peek()
                if tok[0] == "op" and tok[1] in ("-", "!"):
                    self._consume()
                    unary_ops.append((tok[1], tok[2]))
                else:
                    break

            primary = self.parse_primary()
            segments.append((unary_ops, primary))

            tok = self._peek()
            if tok[0] == "op" and tok[1] == "**":
                self._consume()
                ops.append(tok[2])
            else:
                break

        unary_ops, primary = segments[-1]
        node = primary
        for op, pos in reversed(unary_ops):
            node = ("unary", op, node, pos)

        for i in range(len(segments) - 2, -1, -1):
            unary_ops, primary = segments[i]
            node = ("binary", "**", primary, node, ops[i])
            for op, pos in reversed(unary_ops):
                node = ("unary", op, node, pos)

        return node

    def parse_primary(self):
        tok = self._peek()
        kind = tok[0]

        if kind == "int":
            self._consume()
            return ("int", tok[1], tok[2])

        if kind == "bool":
            self._consume()
            return ("bool", tok[1], tok[2])

        if kind == "ident":
            name = tok[1]
            name_pos = tok[2]
            self._consume()

            nxt = self._peek()
            if nxt[0] == "op" and nxt[1] == "(":
                self._consume()
                args = []

                nxt2 = self._peek()
                if nxt2[0] == "op" and nxt2[1] == ")":
                    self._consume()
                    return ("call", name, args, name_pos)

                while True:
                    args.append(self.parse_ternary())
                    tok2 = self._peek()

                    if tok2[0] == "op" and tok2[1] == ",":
                        self._consume()
                        continue

                    if tok2[0] == "op" and tok2[1] == ")":
                        self._consume()
                        break

                    raise ExprError("syntax", tok2[2])

                return ("call", name, args, name_pos)

            return ("var", name, name_pos)

        if kind == "op" and tok[1] == "(":
            self._consume()
            node = self.parse_ternary()
            tok2 = self._peek()
            if tok2[0] == "op" and tok2[1] == ")":
                self._consume()
                return node
            raise ExprError("syntax", tok2[2])

        raise ExprError("syntax", tok[2])


