                    tasks.append(("logic_after_left", op, nd[3], nd[2]))
                    tasks.append(("node", nd[1]))
                else:
                    tasks.append(("apply_bin", op, nd[3]))
                    tasks.append(("node", nd[2]))
                    tasks.append(("node", nd[1]))

